package com.bibliotech.rental.controller;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;@RestControllerAdvice public class ApiExceptionHandler{@ExceptionHandler(NoSuchElementException.class)ResponseEntity<String>n(Exception e){return ResponseEntity.status(404).body(e.getMessage());}@ExceptionHandler(IllegalStateException.class)ResponseEntity<String>c(Exception e){return ResponseEntity.status(409).body(e.getMessage());}@ExceptionHandler(IllegalArgumentException.class)ResponseEntity<String>b(Exception e){return ResponseEntity.badRequest().body(e.getMessage());}}
